"""Apply configuration changes to VyOS devices."""
import sys
from netmiko import ConnectHandler

DEVICES = {
    "HQ-Edge":  {"device_type": "vyos",  "host": "192.168.122.11", "username": "vyos",  "password": "test"},
    "Hub-A":    {"device_type": "vyos",  "host": "192.168.122.12", "username": "vyos",  "password": "test"},
    "Hub-B":    {"device_type": "vyos",  "host": "192.168.122.13", "username": "vyos",  "password": "test"},
}

MIKROTIK = {
    "Branch-1": {"device_type": "mikrotik_routeros", "host": "192.168.122.21", "username": "admin", "password": "test"},
    "Branch-2": {"device_type": "mikrotik_routeros", "host": "192.168.122.22", "username": "admin", "password": "test"},
    "Branch-3": {"device_type": "mikrotik_routeros", "host": "192.168.122.23", "username": "admin", "password": "test"},
    "Branch-4": {"device_type": "mikrotik_routeros", "host": "192.168.122.24", "username": "admin", "password": "test"},
}

HOSTS = {
    "B1-PC2":  {"device_type": "linux", "host": "192.168.122.32", "username": "root", "password": "alpine"},
}

def vyos_config(name, commands):
    dev = DEVICES[name].copy()
    conn = ConnectHandler(**dev, conn_timeout=15, timeout=30)
    print(f"Connected to {name}")
    out = conn.send_config_set(commands, exit_config_mode=False)
    print(out)
    commit_out = conn.commit()
    print(commit_out)
    save_out = conn.send_command_timing("save")
    print(save_out)
    exit_out = conn.send_command_timing("exit")
    print(exit_out)
    conn.disconnect()
    return commit_out

def mikrotik_cmd(name, commands):
    dev = MIKROTIK[name].copy()
    conn = ConnectHandler(**dev, conn_timeout=15, timeout=30)
    print(f"Connected to {name}")
    for cmd in commands:
        out = conn.send_command(cmd, read_timeout=15)
        print(f"  {cmd} -> {out}")
    conn.disconnect()

def linux_cmd(name, commands):
    dev = HOSTS[name].copy()
    conn = ConnectHandler(**dev, conn_timeout=15, timeout=30)
    print(f"Connected to {name}")
    for cmd in commands:
        out = conn.send_command(cmd, read_timeout=15)
        print(f"  {cmd} -> {out}")
    conn.disconnect()

if __name__ == "__main__":
    action = sys.argv[1]

    if action == "hub-a-fix-auth":
        vyos_config("Hub-A", [
            "delete protocols ospf interface eth0 authentication",
            "set protocols ospf interface eth0 authentication md5 key-id 1 md5-key LabArea0Key",
        ])

    elif action == "hub-a-fix-range":
        vyos_config("Hub-A", [
            "delete protocols ospf area 10 range 10.1.0.0/24",
            "set protocols ospf area 10 range 10.1.0.0/16",
        ])

    elif action == "hq-fix-bgp-localpref":
        vyos_config("HQ-Edge", [
            "delete policy route-map ISP-B-IN rule 10 set local-preference",
            "set policy route-map ISP-A-IN rule 10 set local-preference 200",
        ])

    elif action == "hq-fix-ospf-always":
        vyos_config("HQ-Edge", [
            "delete protocols ospf default-information originate always",
            "set protocols ospf default-information originate",
        ])

    elif action == "hq-fix-nat":
        vyos_config("HQ-Edge", [
            "delete nat source rule 110",
            "set nat source rule 110 outbound-interface name eth2",
            "set nat source rule 110 translation address masquerade",
        ])

    elif action == "hub-b-fix-vlink":
        vyos_config("Hub-B", [
            "delete protocols ospf area 10 virtual-link 172.16.10.9",
            "set protocols ospf area 10 virtual-link 10.255.0.2 authentication md5 key-id 1 md5-key LabArea0Key",
        ])

    elif action == "branch2-fix-mtu":
        mikrotik_cmd("Branch-2", [
            "/interface ethernet set [find default-name=ether1] mtu=1500",
        ])

    elif action == "branch2-fix-passive":
        mikrotik_cmd("Branch-2", [
            "/routing ospf interface-template set [find networks=10.1.2.0/24] passive",
        ])

    elif action == "branch3-fix-fw":
        mikrotik_cmd("Branch-3", [
            "/ip firewall filter remove [find chain=forward protocol=ospf]",
        ])

    elif action == "branch4-fix-stub":
        mikrotik_cmd("Branch-4", [
            "/routing ospf area set [find name=area20] type=stub",
        ])

    elif action == "branch4-fix-fw":
        mikrotik_cmd("Branch-4", [
            '/ip firewall filter set [find comment="allow return traffic"] connection-state=established,related',
        ])

    elif action == "b1pc2-fix-mask":
        linux_cmd("B1-PC2", [
            "ip addr del 10.1.1.11/16 dev eth0",
            "ip addr add 10.1.1.11/24 dev eth0",
        ])

    elif action == "verify-frr":
        from run_cmd import run
        name = sys.argv[2]
        result = run([name], ["vtysh -c 'show running-config'"])
        print(result[name]["vtysh -c 'show running-config'"])

    else:
        print(f"Unknown action: {action}")
        sys.exit(1)

