#!/usr/bin/env python3
"""Final verification of the network."""
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

DEVICES = {
    "HQ-Edge":  {"device_type": "vyos",               "host": "192.168.122.11", "username": "vyos",  "password": "test"},
    "Hub-A":    {"device_type": "vyos",               "host": "192.168.122.12", "username": "vyos",  "password": "test"},
    "Hub-B":    {"device_type": "vyos",               "host": "192.168.122.13", "username": "vyos",  "password": "test"},
    "Branch-1": {"device_type": "mikrotik_routeros",  "host": "192.168.122.21", "username": "admin", "password": "test"},
    "Branch-2": {"device_type": "mikrotik_routeros",  "host": "192.168.122.22", "username": "admin", "password": "test"},
    "Branch-3": {"device_type": "mikrotik_routeros",  "host": "192.168.122.23", "username": "admin", "password": "test"},
    "Branch-4": {"device_type": "mikrotik_routeros",  "host": "192.168.122.24", "username": "admin", "password": "test"},
}

HOSTS = {
    "B1-PC1": {"device_type": "linux", "host": "192.168.122.31", "username": "root", "password": "alpine", "lab_ip": "10.1.1.10"},
    "B1-PC2": {"device_type": "linux", "host": "192.168.122.32", "username": "root", "password": "alpine", "lab_ip": "10.1.1.11"},
    "B2-PC1": {"device_type": "linux", "host": "192.168.122.33", "username": "root", "password": "alpine", "lab_ip": "10.1.2.10"},
    "B2-PC2": {"device_type": "linux", "host": "192.168.122.34", "username": "root", "password": "alpine", "lab_ip": "10.1.2.11"},
    "B3-PC1": {"device_type": "linux", "host": "192.168.122.35", "username": "root", "password": "alpine", "lab_ip": "10.1.3.10"},
    "B3-PC2": {"device_type": "linux", "host": "192.168.122.36", "username": "root", "password": "alpine", "lab_ip": "10.1.3.11"},
    "B4-PC1": {"device_type": "linux", "host": "192.168.122.37", "username": "root", "password": "alpine", "lab_ip": "10.2.1.10"},
    "B4-PC2": {"device_type": "linux", "host": "192.168.122.38", "username": "root", "password": "alpine", "lab_ip": "10.2.1.11"},
    "B4-PC3": {"device_type": "linux", "host": "192.168.122.39", "username": "root", "password": "alpine", "lab_ip": "10.2.2.10"},
    "B4-PC4": {"device_type": "linux", "host": "192.168.122.40", "username": "root", "password": "alpine", "lab_ip": "10.2.2.11"},
}

GUEST_HOSTS = {"B4-PC3", "B4-PC4"}
NON_GUEST = [h for h in HOSTS if h not in GUEST_HOSTS]

def ping_from_host(src_name, dst_ip):
    dev = {k: v for k, v in HOSTS[src_name].items() if k != "lab_ip"}
    try:
        conn = ConnectHandler(**dev, conn_timeout=10, timeout=15)
        out = conn.send_command(f"ping -c 2 -W 3 {dst_ip}", read_timeout=15)
        conn.disconnect()
        return "0% packet loss" in out or "0 packet loss" in out or " 0% loss" in out
    except Exception as e:
        return f"ERROR: {e}"

def run_ping_tests():
    results = {}
    tasks = []

    with ThreadPoolExecutor(max_workers=5) as pool:
        # Non-guest to non-guest
        for src in NON_GUEST:
            for dst in NON_GUEST:
                if src == dst:
                    continue
                dst_ip = HOSTS[dst]["lab_ip"]
                tasks.append((pool.submit(ping_from_host, src, dst_ip), src, dst, dst_ip, "non-guest-to-non-guest"))

        # Guest to guest
        for src in GUEST_HOSTS:
            for dst in GUEST_HOSTS:
                if src == dst:
                    continue
                dst_ip = HOSTS[dst]["lab_ip"]
                tasks.append((pool.submit(ping_from_host, src, dst_ip), src, dst, dst_ip, "guest-to-guest"))

        # Guest to non-guest (should fail)
        for src in GUEST_HOSTS:
            for dst in NON_GUEST:
                dst_ip = HOSTS[dst]["lab_ip"]
                tasks.append((pool.submit(ping_from_host, src, dst_ip), src, dst, dst_ip, "guest-to-nonguest"))

        # Non-guest to guest (should fail)
        for src in NON_GUEST:
            for dst in GUEST_HOSTS:
                dst_ip = HOSTS[dst]["lab_ip"]
                tasks.append((pool.submit(ping_from_host, src, dst_ip), src, dst, dst_ip, "nonguest-to-guest"))

        # Internet pings
        for src in HOSTS:
            for target in ["8.8.8.8", "1.1.1.1"]:
                tasks.append((pool.submit(ping_from_host, src, target), src, target, target, "internet"))

        for future, src, dst, dst_ip, category in tasks:
            success = future.result()
            results[(src, dst, category)] = success

    return results

if __name__ == "__main__":
    print("Running ping tests...")
    results = run_ping_tests()

    # Analyze results
    print("\n=== NON-GUEST TO NON-GUEST (should all pass) ===")
    ng_pass = 0
    ng_fail = []
    for (src, dst, cat), ok in results.items():
        if cat == "non-guest-to-non-guest":
            if ok == True:
                ng_pass += 1
            else:
                ng_fail.append(f"  FAIL: {src} -> {dst}")
    print(f"  Passed: {ng_pass}, Failed: {len(ng_fail)}")
    for f in ng_fail:
        print(f)

    print("\n=== GUEST TO GUEST (should pass) ===")
    for (src, dst, cat), ok in results.items():
        if cat == "guest-to-guest":
            status = "PASS" if ok == True else "FAIL"
            print(f"  {status}: {src} -> {dst}")

    print("\n=== GUEST TO NON-GUEST (should fail - policy) ===")
    g2ng_correct = 0
    g2ng_wrong = []
    for (src, dst, cat), ok in results.items():
        if cat == "guest-to-nonguest":
            if ok != True:
                g2ng_correct += 1
            else:
                g2ng_wrong.append(f"  WRONG (should fail): {src} -> {dst}")
    print(f"  Correctly blocked: {g2ng_correct}, Incorrectly passed: {len(g2ng_wrong)}")
    for f in g2ng_wrong:
        print(f)

    print("\n=== NON-GUEST TO GUEST (should fail - policy) ===")
    ng2g_correct = 0
    ng2g_wrong = []
    for (src, dst, cat), ok in results.items():
        if cat == "nonguest-to-guest":
            if ok != True:
                ng2g_correct += 1
            else:
                ng2g_wrong.append(f"  WRONG (should fail): {src} -> {dst}")
    print(f"  Correctly blocked: {ng2g_correct}, Incorrectly passed: {len(ng2g_wrong)}")
    for f in ng2g_wrong:
        print(f)

    print("\n=== INTERNET PINGS (should all pass) ===")
    inet_pass = 0
    inet_fail = []
    for (src, dst, cat), ok in results.items():
        if cat == "internet":
            if ok == True:
                inet_pass += 1
            else:
                inet_fail.append(f"  FAIL: {src} -> {dst}")
    print(f"  Passed: {inet_pass}, Failed: {len(inet_fail)}")
    for f in inet_fail:
        print(f)

